// src/desktop-main.ts
import { app, ipcMain, shell } from "electron";
import { createServer } from "node:http";
import path from "node:path";

// src/lib/electron-ipc.ts
var MANAGED_AUTH_IPC = {
  openExternal: "managed-auth:open-external",
  redirectTarget: "managed-auth:redirect-target",
  deepLink: "managed-auth:deep-link"
};

// src/lib/scheme.ts
var applicationScheme = (applicationId) => `runable-${applicationId}`;

// src/desktop-main.ts
function createManagedDeepLinks(options) {
  const { getWindow } = options;
  const scheme = options.applicationId ? applicationScheme(options.applicationId) : undefined;
  const isDeepLink = (value) => scheme !== undefined && value.startsWith(`${scheme}://`);
  const pending = [];
  const sendDeepLink = (url) => {
    const win = getWindow();
    if (!win || win.webContents.isLoading()) {
      pending.push(url);
      return;
    }
    if (win.isMinimized())
      win.restore();
    win.focus();
    win.webContents.send(MANAGED_AUTH_IPC.deepLink, url);
  };
  app.on("browser-window-created", (_event, win) => {
    win.webContents.once("did-finish-load", () => {
      while (pending.length)
        sendDeepLink(pending.shift());
    });
  });
  const deliver = options.onDeepLink ?? sendDeepLink;
  const handleArgv = (argv) => {
    const url = argv.find(isDeepLink);
    if (url)
      deliver(url);
  };
  if (scheme) {
    if (process.defaultApp && process.argv[1]) {
      app.setAsDefaultProtocolClient(scheme, process.execPath, [path.resolve(process.argv[1])]);
    } else {
      app.setAsDefaultProtocolClient(scheme);
    }
  }
  app.on("open-url", (event, url) => {
    if (!isDeepLink(url))
      return;
    event.preventDefault();
    deliver(url);
  });
  ipcMain.handle(MANAGED_AUTH_IPC.openExternal, (_event, url) => {
    const isHttpUrl = URL.canParse(url) && ["http:", "https:"].includes(new URL(url).protocol);
    if (!isHttpUrl)
      return;
    return shell.openExternal(url);
  });
  const redirectTarget = app.isPackaged ? undefined : startLoopbackRelay(deliver);
  ipcMain.handle(MANAGED_AUTH_IPC.redirectTarget, () => redirectTarget);
  return { scheme, isDeepLink, handleArgv, sendDeepLink };
}
var RELAY_PAGE = `<!doctype html><meta charset="utf-8"><title>Sign-in complete</title>
<body style="font-family:system-ui;display:grid;place-items:center;min-height:100vh;margin:0;background:#0b0b0c;color:#fafafa">
<p id="msg">Completing sign-in…</p>
<script>
  const hash = location.hash;
  history.replaceState(null, "", "/");
  fetch("/deliver", { method: "POST", body: hash })
    .then(() => { document.getElementById("msg").textContent = "Signed in — return to the app."; })
    .catch(() => { document.getElementById("msg").textContent = "Could not reach the app."; });
</script>`;
function startLoopbackRelay(deliver) {
  return new Promise((resolve) => {
    const server = createServer((req, res) => {
      if (req.method === "POST" && req.url === "/deliver") {
        let body = "";
        req.on("data", (chunk) => {
          body += chunk;
        });
        req.on("end", () => {
          const address = server.address();
          if (body.startsWith("#") && address && typeof address === "object") {
            deliver(`http://localhost:${address.port}/${body}`);
          }
          res.writeHead(204).end();
        });
        return;
      }
      res.writeHead(200, { "content-type": "text/html; charset=utf-8" }).end(RELAY_PAGE);
    });
    server.on("error", () => resolve(undefined));
    server.unref();
    server.listen(0, "127.0.0.1", () => {
      const address = server.address();
      resolve(address && typeof address === "object" ? `http://localhost:${address.port}/` : undefined);
    });
  });
}
export {
  createManagedDeepLinks
};
